def queen_count(board, q):
    n = len(board)
    free = [(r, c) for r in range(n) for c in range(n) if board[r][c] == '.']
    placed = []

    def safe(r, c):
        return all(r != a and c != b and abs(r - a) != abs(c - b) for a, b in placed)

    def walk(left):
        if left == 0:
            return 1
        total = 0
        for r, c in free:
            if (r, c) not in placed and safe(r, c):
                placed.append((r, c))
                total += walk(left - 1)
                placed.pop()
        return total

    return walk(q)
